use std::{env,fs,time::Instant};use wasmtime::{Config,Engine,Module,OptLevel};
fn main(){let args:Vec<_>=env::args().collect();let bytes=fs::read(&args[1]).unwrap();let mut config=Config::new();if args.get(2).map(String::as_str)==Some("none"){config.cranelift_opt_level(OptLevel::None);}let engine=Engine::new(&config).unwrap();let start=Instant::now();if args.get(2).map(String::as_str)==Some("validate"){match Module::validate(&engine,&bytes){Ok(())=>println!("accepted=true elapsed_ms={} bytes={}",start.elapsed().as_millis(),bytes.len()),Err(error)=>{eprintln!("validation rejected: {error}");std::process::exit(2)}}return;}let module=Module::new(&engine,&bytes).unwrap();let elapsed=start.elapsed();let mut imports:Vec<_>=module.imports().map(|x|format!("{}:{}:{:?}",x.module(),x.name(),x.ty())).collect();let mut exports:Vec<_>=module.exports().map(|x|format!("{}:{:?}",x.name(),x.ty())).collect();imports.sort();exports.sort();println!("elapsed_ms={} bytes={} imports={} exports={}",elapsed.as_millis(),bytes.len(),imports.len(),exports.len());for x in imports{println!("import {x}");}for x in exports{println!("export {x}");}}
